import json
from typing import Dict, List

class RefactorPython:
    def __init__(self, folder_content: str, audit_report: str):
        self.folder_contents = json.loads(folder_content)  
        self.audit_report = json.loads(audit_report)

    def apply_fixes(self) -> Dict[str, List[Dict[str, str]]]:
        fixes = {"files": []}    

        for filename in self.folder_contents:  
            file_content = self.folder_contents[filename]   

            fixed_code = ""   

            for issue in self.audit_report['issues']:  
                problem, fix = issue['problem'], issue['fix']

                if filename + ':' + str(problem['line']) in file_content: 
                    fixed_code += file_content[:problem['line']]  

                    for single_fix in fix:   
                        if filename + ':' + str(single_fix['line']) == problem['file']:  
                            fixed_code += single_fix['fix']  

                    fixed_code += '\n' 

            fixes["files"].append({"file": filename, "fixed_code": fixed_code})   

        return fixes    
